//! CoreFoundation ownership and value conversion.
//!
//! Ownership is **not** hand-rolled here. `core_foundation::base::CFType` is the reference-counted
//! owner: its `Drop` calls `CFRelease` (generated by `declare_TCFType!`), and there are exactly two
//! ways to build one -- [`owned`] for a `+1` reference a copy/create call handed us, [`retained`] for
//! a borrow that has to outlive its container. `CFType` is not `Copy`, so "one `+1` reference, two
//! owners" -- the under-release that used to trap `computer_snapshot` inside `CFGetTypeID` -- is no
//! longer expressible.
//!
//! The raw `core-foundation-sys` calls that remain only *read* a value that an owner above keeps
//! alive; none of them crosses an ownership boundary.

use core_foundation::base::{CFType, TCFType};
use core_foundation::string::CFString;
use core_foundation_sys::{
    array::{CFArrayGetCount, CFArrayGetTypeID, CFArrayGetValueAtIndex, CFArrayRef},
    base::{CFGetTypeID, CFTypeRef},
    number::{
        CFBooleanGetTypeID, CFBooleanGetValue, CFNumberGetTypeID, CFNumberGetValue,
        kCFNumberSInt64Type,
    },
    string::{CFStringGetCString, CFStringGetTypeID, kCFStringEncodingUTF8},
};
use std::ffi::{CStr, c_char, c_void};

/// Adopt a `+1` reference returned by a `CFCopy*` / `CFCreate*` / `AXUIElementCreate*` call.
pub(crate) fn owned(raw: CFTypeRef) -> Option<CFType> {
    if raw.is_null() {
        return None;
    }
    // SAFETY: the caller passes the owned `+1` reference of a copy or create call; the returned
    // value's `Drop` releases it exactly once.
    Some(unsafe { CFType::wrap_under_create_rule(raw) })
}

/// Take one extra reference to a value borrowed from a container, so it can outlive that container.
pub(crate) fn retained(raw: CFTypeRef) -> Option<CFType> {
    if raw.is_null() {
        return None;
    }
    // SAFETY: `raw` is a live CoreFoundation value owned by a container that outlives this call;
    // retaining it gives the returned value its own reference, released on drop.
    Some(unsafe { CFType::wrap_under_get_rule(raw) })
}

/// A CoreFoundation string for an attribute / action name.
pub(crate) fn string(text: &str) -> CFString {
    CFString::new(text)
}

fn is_type(value: &CFType, type_id: unsafe extern "C" fn() -> usize) -> bool {
    // SAFETY: `value` is a live CoreFoundation value and the getter only reads a framework type id.
    unsafe { CFGetTypeID(value.as_CFTypeRef()) == type_id() }
}

/// `true` when `value` is a CoreFoundation string.
pub(crate) fn is_string(value: &CFType) -> bool {
    is_type(value, CFStringGetTypeID)
}

/// `true` when `value` is a CoreFoundation array.
pub(crate) fn is_array(value: &CFType) -> bool {
    is_type(value, CFArrayGetTypeID)
}

fn is_boolean(value: &CFType) -> bool {
    is_type(value, CFBooleanGetTypeID)
}

fn is_number(value: &CFType) -> bool {
    is_type(value, CFNumberGetTypeID)
}

/// Copy a CF string into Rust text, or `None` when it is not a string / does not fit the buffer.
pub(crate) fn to_string(value: &CFType) -> Option<String> {
    if !is_string(value) {
        return None;
    }
    let mut buffer = vec![c_char::default(); 8192];
    // SAFETY: `value` is a CF string (checked above) and `buffer` is a valid, sized destination.
    let ok = unsafe {
        CFStringGetCString(
            value.as_CFTypeRef().cast(),
            buffer.as_mut_ptr(),
            buffer.len() as isize,
            kCFStringEncodingUTF8,
        )
    };
    if ok == 0 {
        return None;
    }
    // SAFETY: on success `CFStringGetCString` wrote a NUL-terminated string into the buffer.
    let text = unsafe { CStr::from_ptr(buffer.as_ptr()) };
    Some(text.to_string_lossy().into_owned())
}

/// Read a CF number as an integer.
pub(crate) fn to_i64(value: &CFType) -> Option<i64> {
    if !is_number(value) {
        return None;
    }
    let mut out: i64 = 0;
    // SAFETY: `value` is a CF number and `out` is a valid `i64` destination.
    let ok = unsafe {
        CFNumberGetValue(
            value.as_CFTypeRef().cast(),
            kCFNumberSInt64Type,
            (&raw mut out).cast::<c_void>(),
        )
    };
    ok.then_some(out)
}

/// Read a CF boolean.
pub(crate) fn to_bool(value: &CFType) -> Option<bool> {
    if !is_boolean(value) {
        return None;
    }
    // SAFETY: `value` is a CF boolean (checked above).
    Some(unsafe { CFBooleanGetValue(value.as_CFTypeRef().cast()) })
}

/// Take one reference to every element of a CF array. Each element is an owner of its own.
pub(crate) fn array_items(value: &CFType) -> Vec<CFType> {
    if !is_array(value) {
        return Vec::new();
    }
    let array: CFArrayRef = value.as_CFTypeRef().cast();
    // SAFETY: `value` is a CF array (checked above).
    let count = unsafe { CFArrayGetCount(array) };
    (0..count.max(0))
        .filter_map(|index| {
            // SAFETY: `index` is within `0..CFArrayGetCount`; the item is borrowed from the array
            // and `retained` gives it a reference of its own before the array can go away.
            let item = unsafe { CFArrayGetValueAtIndex(array, index) };
            retained(item)
        })
        .collect()
}
